ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Documentation';OUT.mkdir(exist_ok=True)
FONT=ROOT/'Documentation/Fonts'
VERSION='0.3.2'
VALIDATED=os.environ.get('IRCHOIR_AUDIT_VALIDATED')=='1'
RUN=os.environ.get('GITHUB_RUN_ID','')
COMMIT=os.environ.get('GITHUB_SHA','')
AUDIT_STATUS='PASS' if VALIDATED else 'Release gate - see workflow evidence'
# Authoring dependency; PDFs are already generated for recipients.
pdfmetrics.registerFont(TTFont('IRSans',str(FONT/'DejaVuSans.ttf')))
pdfmetrics.registerFont(TTFont('IRSans-Bold',str(FONT/'DejaVuSans-Bold.ttf')))
NAVY=colors.HexColor('#0a101d');GOLD=colors.HexColor('#edbb79');MUTED=colors.HexColor('#566276');PALE=colors.HexColor('#f3f5f8')
WIDTH,HEIGHT=612,792;CONTENT=516
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='IRTitle',fontName='IRSans-Bold',fontSize=25,leading=31,textColor=NAVY,spaceAfter=12))
styles.add(ParagraphStyle(name='IRH',fontName='IRSans-Bold',fontSize=15,leading=20,textColor=NAVY,spaceBefore=10,spaceAfter=7))
styles.add(ParagraphStyle(name='IRBody',fontName='IRSans',fontSize=10.6,leading=15.5,textColor=NAVY,spaceAfter=9))
styles.add(ParagraphStyle(name='IRSmall',fontName='IRSans',fontSize=8.7,leading=12,textColor=MUTED,spaceAfter=7))
styles.add(ParagraphStyle(name='IRCell',fontName='IRSans',fontSize=9.4,leading=13.5,textColor=NAVY))
styles.add(ParagraphStyle(name='IRCellWhite',fontName='IRSans-Bold',fontSize=9.3,leading=13,textColor=colors.white))

def p(text,style='IRBody'):return Paragraph(text,styles[style])
def title(text,sub=None):return [p(text,'IRTitle')]+([p(sub,'IRSmall')] if sub else [])
def h(text):return p(text,'IRH')
def note(text):
 t=Table([[p(text)]],colWidths=[CONTENT]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#fff3df')),('BOX',(0,0),(-1,-1),0.6,GOLD),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),5)]));return t

def table(headers,rows,widths=None):
 widths=widths or [145,371]
 data=[[p(escape(x),'IRCellWhite') for x in headers]]+[[p(escape(str(x)),'IRCell') for x in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[PALE,colors.white]),('LINEBELOW',(0,0),(-1,0),1.2,GOLD)]))
 return t

def img(path,width):
 w,h=PILImage.open(path).size;return Image(str(path),width=width,height=width*h/w)

def build(filename,label,story):
 def page(c,doc):
  c.saveState();c.setFillColor(NAVY);c.rect(0,HEIGHT-75,WIDTH,75,fill=1,stroke=0)
  c.drawImage(str(ROOT/'Branding/IRChoir-Logo.png'),45,HEIGHT-65,width=174,height=58,mask='auto',preserveAspectRatio=True,anchor='c')
  c.setFillColor(GOLD);c.setFont('IRSans-Bold',9);c.drawRightString(WIDTH-48,HEIGHT-39,label.upper())
  c.setStrokeColor(GOLD);c.setLineWidth(0.7);c.line(48,38,WIDTH-48,38)
  c.setFillColor(MUTED);c.setFont('IRSans',8);c.drawString(48,24,'I.R.Choir  |  v0.3.2 prototype  |  23 October 2026')
  c.drawRightString(WIDTH-48,24,str(doc.page));c.restoreState()
 doc=SimpleDocTemplate(str(OUT/filename),pagesize=(WIDTH,HEIGHT),leftMargin=48,rightMargin=48,topMargin=96,bottomMargin=54,title='I.R.Choir - '+label,author='I.R.Choir')
 doc.build(story,onFirstPage=page,onLaterPages=page)

quick=[]
quick+=title('Quick start','Install the validated Mac build and turn one recording into a choir.')
quick+=[note('<b>Mac installer included.</b> Universal AU/VST3 with release gates for audio tests, package installation, pluginval and auval. Read the included test report and raw evidence. The installer is unsigned and not notarized.'),h('1. Install I.R.Choir'),p('Quit your DAW. Open <b>Installer/I.R.Choir-0.3.2-unsigned.dmg</b> and run its .pkg. Follow the Installer prompts, then restart your DAW and rescan plugins. Target: macOS 12 or later, Intel and Apple Silicon. Automated runtime checks run on Apple Silicon; test your own DAW before important work.'),table(['Format','Installed bundle'],[['AU','/Library/Audio/Plug-Ins/Components/IRChoir.component'],['VST3','/Library/Audio/Plug-Ins/VST3/IRChoir.vst3']],[80,436]),h('2. Import one vocal recording'),p('Open the plugin. Click <b>Load vocal</b>, or drop one WAV, AIFF or FLAC file on the editor. Wait for its filename to appear; <b>File input</b> selects the recording. Press <b>Play</b>. Each choir layer uses the same recorded words and performance.'),h('3. Shape your choir'),p('Start with <b>Intimate</b> or <b>Wide</b> in <b>Unison</b>. Adjust Ensemble Size, Choir Mix, Stereo Width and Room. Open <b>Reverb space</b> for its toggles and controls. Lower Output if clipping appears.'),p('<b>Loop</b> repeats; Stop rewinds. Playback is manual and independent of the DAW transport. Keep the DAW audio engine running. Turn File input off to use your DAW track audio again.'),p('Accepted files: mono/stereo, 8-192 kHz, up to five minutes and 128 MiB decoded. Keep the original recording: projects store its path, not embedded audio.','IRSmall')]
quick+=[PageBreak()]+title('Meet your choir','Actual native editor capture from the successful Mac smoke test.')
quick+=[img(ROOT/'TestEvidence/IRChoir-Native-Interface.png',460),Spacer(1,10),table(['Area','Start with this'],[['Import row','Load vocal, Play/Stop, Loop and File input. No lyric entry is needed.'],['Choir stage','Click to select; shift-click to group. Drag for pan/level; double-click to mute.'],['Conductor','Move vertically for intensity and horizontally for space.'],['Control pages','Performance, humanize, EQ/dynamics, delay, four-part controls and Reverb space.'],['Meters','Watch clipping and use Mono audition to check cancellation.']],[112,404]),p('The engine layers your recording with delay, pitch shifts and tonal filters. It is not a trained choir model. Real-vocal listening and testing in your own DAW remain necessary. Current documents are included both alongside the DMG and inside its Documentation folder.','IRSmall')]
build('IRChoir-Quick-Start.pdf','Quick start',quick)

manual=[]
manual+=title('User guide','A practical guide to the current native vocal ensemble effect.')
manual+=[h('What I.R.Choir does'),p('I.R.Choir creates an ensemble from a vocal audio input using delayed, modulated and pitch-shifted layers. You can position and mix those layers, shape their synthetic tone colors, and add master effects.'),note('<b>Prototype boundary:</b> the result is not a trained choir conversion model. Bass, tenor, alto and soprano labels organize processed parts; they are not sampled human voice types.'),h('The signal path'),p('DAW track audio or imported vocal → choir layers and part processing → dry/wet blend → low/high EQ → saturation → linked compression → delay → algorithmic room → output gain → optional mono audition.'),h('Choose a simple starting workflow'),table(['Goal','Starting point'],[['Subtle vocal thickening','Tight Doubles; low Room and moderate Choir Mix.'],['Wide backing layer','Wide Backing or Wide; adjust Stereo Width and monitor mono.'],['Atmospheric texture','Cloud or Dream Haze; listen carefully to consonants and pitch stability.'],['Relative harmony','Choose four relative parts and edit the four interval knobs.'],['MIDI harmony','Route input audio plus MIDI notes; use a clear monophonic guide.']]),h('Before important work'),p('Test on a copy of a DAW project. Listen at matched loudness against bypass. The automated tests establish software behavior, not musical realism or target-host reliability.')]
manual+=[PageBreak()]+title('Import one vocal recording','Use the recorded lyrics and melody as the source for every choir layer.')
manual+=[h('Load and play'),p('Click <b>Load vocal</b>, or drag one WAV, AIFF or FLAC file onto the editor. After decoding finishes, its filename appears and <b>File input</b> becomes selected. Play stays unavailable until a recording is ready. Import does not start playback automatically. Press <b>Play</b> to send the recording through the full choir engine.'),table(['Control','Behavior'],[['Play / Stop','Play starts from the beginning. Stop rewinds; existing effects tails may decay.'],['Loop','Repeat the recording while playback is active. Short fades soften loop boundaries.'],['File input on','Replace the incoming DAW audio with the imported recording.'],['File input off','Process the audio coming from your DAW track instead.'],['Replace recording','Load another file. A failed import retains the previous successfully loaded recording.']]),h('Create the choir'),p('Start in Unison with Intimate or Wide. Adjust Ensemble Size, singers/groups and Humanize. Four-part mode adds relative harmonies; MIDI mode needs routed notes. Every layer reuses the recorded words; no lyric entry or separate recording of each part is needed.'),h('File limits and project recall'),p('Limits: mono/stereo, 8-192 kHz, five minutes, 128 MiB decoded. Files decode locally in the background. Projects remember the absolute file path, File input and Loop; playback restores stopped. Audio is not embedded. Keep the original or relink with Load vocal after moving it. Missing project files remain silent and retain their reference for relinking; previous audio is not substituted. A failed manual import retains the prior loaded recording. Presets and A/B do not package recordings.'),p('Playback is manual and independent of the DAW transport. Keep the host audio engine running; some hosts require transport playback. Pitch shifts can soften consonants or sound synthetic. Automated checks do not establish natural choir realism.','IRSmall')]
manual+=[PageBreak()]+title('The interactive stage')
manual+=[table(['Action','Result'],[['Click a singer','Select it for individual level, pan, mute, solo and synthetic color.'],['Shift-click','Add or remove singers from the selection.'],['Drag a selected singer','Move the selection in stereo and adjust its level. Vertical movement is visually limited to keep rows legible.'],['Click empty stage space','Clear a group selection before selecting one singer.'],['Double-click','Toggle that singer mute.'],['Bass / Tenor / Alto / Soprano','Select every active layer in that part.'],['All singers','Select every active layer.'],['Group pan','Apply a relative pan offset; the control returns to zero after dragging.'],['Group level','Set all selected layers to the displayed level.'],['Group mute / solo','Toggle the selection together. Solo affects wet layers only.']]),h('Formations'),p('<b>Semicircle</b> curves the stage; <b>Tight cluster</b> narrows placement; <b>Wide rows</b> spreads singers across the stereo field. Applying a formation resets singer pan and level. Reapply after changing ensemble size to space the current singers again.'),h('Animation'),p('Full and Subtle modes animate the actual layer meters. Distinct faces, hairstyles and choir robes identify the visual layers; these are not separate voice models. Reduced motion removes mouth and singer glow animation while retaining slow meter refresh. The Humanize sliders provide a conventional alternative to dragging the conductor pad.')]
manual+=[PageBreak()]+title('Performance and humanize')
manual+=[table(['Control','What changes'],[['Ensemble Size','2 to 32 active layers. Higher counts increase processing cost.'],['Choir Mix','Blend the original vocal and processed ensemble. At 100%, only wet layers remain.'],['Stereo Width','Scale individual pan positions; there is no pan effect in a mono output.'],['Human Motion','Slow delay modulation across singers.'],['Timing Looseness','Vary the small delay offsets between layers.'],['Pitch Drift','Slow pitch variation, expressed in cents.'],['Vibrato','Additional pitch movement in cents.'],['Intensity','Layer gain and modulation intensity; the conductor vertical axis.'],['Space','Controls ambience strength with Room; the conductor horizontal axis.'],['Synthetic Character','Blend each layer with its warm/airy/dark/bright filter color.'],['Output','Final gain after all effects. Clip indication is not limiting.']]),h('Getting a natural result'),p('Use small timing and pitch amounts before increasing layer count. Keep some dry signal for intelligibility. Excessive width or movement can weaken consonants or produce phase cancellation. A 12-layer setting is not automatically better than a 4-layer setting.'),h('Synthetic voice colors'),p('Warm, Airy, Dark and Bright are tonal filters, not voice identities. Distinct recorded or AI singers require separately licensed recordings or a trained model that is not included.')]
manual+=[PageBreak()]+title('Effects and metering')
manual+=[table(['Effect','Use and limits'],[['Low / High EQ','Tone shelves around the low and high regions; not a full surgical equalizer.'],['Saturation','Adds nonlinear color. Increase carefully and compare at matched loudness.'],['Compression','Linked stereo envelope control to reduce high-level peaks; no automatic makeup gain.'],['Delay Mix','Add delayed repeats.'],['Delay Time','50-1000 ms. Changes are smoothed and can create tape-like pitch movement.'],['Feedback','Controls repeat decay; limited to 0.8 for stability.'],['Room type','Six algorithmic spaces, including Chamber, Plate-style and Tunnel-style; no measured impulse responses.'],['Room','Master ambience blend; also affected by the conductor Space control.']]),h('Read the meters'),p('<b>L/R</b> show peak output in dBFS. <b>CLIP</b> stays lit after an overload until cleared. <b>Correlation</b> approaches +1 for similar left/right signals and can go negative when they oppose each other. <b>Mono RMS</b> measures the level after summing, before Mono audition is applied.'),p('Use Mono audition while adjusting width. If the choir becomes much quieter or thin, reduce width and motion and compare again. The vocal guide frequency is an approximate pitch estimate, not a tuning meter.'),h('Smoothing'),p('The engine ramps major mix, level, gate, conductor and FX changes. This reduces abrupt control jumps but does not establish artifact-free sound under every automation pattern.')]
manual+=[PageBreak()]+title('Shape the reverb','Open Reverb space from the control-page menu.')
manual+=[p('The place browser offers 55 independent algorithmic designs in 18 categories. Choose a place at the lower left of Reverb space; changes marked (edited) remain adjustable and recall with sound presets. A selection edits only reverb and is one undo transaction. See SPACE-PRESETS.txt for the complete catalog. The six underlying algorithms are Studio, Hall, Cathedral, Chamber, Plate-style and Tunnel-style. No measured venue models or EastWest recordings are included.'),table(['Control','Action'],[['Reverb on','Enable the wet return; switching off restores the dry signal with a short fade.'],['Mono send','Sum the input sent to the reverb while leaving the dry stereo image intact.'],['Low cut / High cut','Toggle the send filters; frequency knobs set their cutoff.'],['Freeze','Hold the reverb tail. Turn off to release it; lower Room before experimenting.'],['Wet only','Hear the reverb return without the dry vocal. Reverb off restores dry audio.'],['Pre-delay','0-200 ms before the reverb; Tunnel-style adds 9 ms of spacing.'],['Decay shape','Relative room decay adjustment, not calibrated seconds.'],['Reverb width','Set the stereo width of the wet return.'],['Damping','Soften high frequencies as the reverb decays.'],['Room / conductor Space','Control the wet return amount from Performance and the conductor pad.']]),p('Start with Hall, a low Room level, 12-30 ms pre-delay and some low cut. Use wet-only listening to tune the space, then return to the full mix. These recommendations are starting points for listening, not measured acoustic models.')]
manual+=[PageBreak()]+title('The Reverb display','Illustrated space and a control-linked shape display.')
manual+=[img(ROOT/'TestEvidence/IRChoir-Reverb-Interface.png',460),Spacer(1,10),p('The room illustration follows the selected place category: arches, studios, caves, forests or abstract plate/tank shapes. A miniature choir uses the current layer positions and audio activity. It is an original illustration, not a venue photograph or acoustic measurement.'),p('The lower plot follows Pre-delay and relative Decay Shape. It has no measured time axis and is not an impulse response or sonogram. The Reverb page keeps its existing parameter knobs and toggles below the illustration. Edit individual singers on the choir pages; hidden singer hit targets are disabled here.')]
manual+=[PageBreak()]+title('Presets, favourites and history')
manual+=[table(['Factory preset','Intended character'],[['Intimate','4 restrained layers with little ambience.'],['Wide','12 broad backing layers.'],['Cloud','24 layers with more motion and space.'],['Massive','32 dense layers.'],['Tight Doubles','2 layers, subtle movement, no room.'],['Wide Backing','12 layers, a little compression and high tone.'],['Dream Haze','24 layers with delay and darker high tone.'],['Cathedral','16 layers with the largest algorithmic room.'],['Crowd Wash','32 layers with stronger movement and color.']]),h('Save and find your own sounds'),p('Type a name and click Save. A new .irchoir.xml file is created in your user application-data location under IRChoir/Presets. Existing files are not silently overwritten. Star the current preset to mark it as a favourite; Favourites filters the browser.'),h('A/B and undo'),p('A/B saves the current side before loading the other. Copy sends the current sound to the other side. Both snapshots survive closing the editor while the plugin instance exists, but only the current sound is saved with a DAW project.'),p('Undo and Redo cover parameter edits. Factory-preset edits, including resets to defaults, are undoable together. Whole preset-file loading and A/B replacement are separate state operations. Preset names do not show every unsaved change. Loading a factory preset resets sonic parameters and singer edits; animation preference is retained.')]
manual+=[PageBreak()]+title('Four parts and MIDI')
manual+=[h('Relative parts'),p('Each active layer is assigned to one of four repeating parts. Set their levels independently and choose intervals from -12 to +12 semitones. The default offsets are -12, -5, 0 and +7 relative to your incoming vocal. This creates processed harmony layers; it does not change the source into four authentic human voice types.'),h('MIDI targets'),p('Choose MIDI note targets, route MIDI into the plugin using your host, and send a stable monophonic vocal to the audio input. The engine estimates the input pitch and shifts parts toward held MIDI notes. Sustain and channel-aware note release are supported.'),table(['Behavior','Current implementation'],[['Which notes?','The lowest four unique held notes. When fewer notes are held, the highest available note repeats.'],['Shift range','At most one octave up or down relative to the detected input.'],['No held notes','The wet layers are gated off. Dry signal may remain, depending on Choir Mix.'],['No stable pitch','The MIDI wet layers are gated off; unvoiced sounds can be affected.'],['Guide range','Approximate monophonic detection, about 65-1000 Hz.'],['Formants','No formant preservation; large shifts can sound synthetic.']]),h('Example'),p('With a clear A3 guide (about 220 Hz), try held notes A2, E3, A3 and E4. Begin with low movement and no master effects. Judge note transitions and consonant clarity before adding ambience.'),h('AU routing'),p('The AU is a MIDI-controlled audio effect. In Logic and other hosts, the route may differ from a normal audio insert. MIDI alone does not create sound; a vocal audio source is still required.')]
manual+=[PageBreak()]+title('Troubleshooting and care')
manual+=[table(['Symptom','Check'],[['No plugin in the DAW','Confirm the package installed the correct format, restart and rescan. Read host scan errors.'],['No wet sound','Check File input and Play for imported audio, or DAW track input. Check mutes/solos, Choir Mix and held notes in MIDI mode.'],['Metallic or smeared sound','Reduce shifts, drift, vibrato and motion. Try fewer layers and a cleaner vocal. Granular artifacts remain a known limitation.'],['Clipping','Reduce Output, drive, EQ boost, delay feedback and layer level.'],['Weak mono sound','Reduce width/motion, audition the mono sum and watch correlation.'],['Preset cannot save','Check application-data folder permissions. The UI reports failure rather than claiming success.'],['Too much CPU','Use fewer layers. Try Subtle or Reduced motion. Measure in the actual DAW at your buffer size.'],['macOS blocks the file','Verify the build origin and signing status. Do not disable Gatekeeper globally.']]),h('Remove the plugin'),p('Quit the DAW and remove IRChoir.component from /Library/Audio/Plug-Ins/Components and IRChoir.vst3 from /Library/Audio/Plug-Ins/VST3. Rescan. Your separately stored presets remain.'),h('Report a reproducible problem'),p('Record the plugin version, Mac model/chip, macOS, DAW/version, AU or VST3, sample rate, buffer size, preset and exact steps. Include scan/crash logs. Supply a short audio example only if you own or have permission to share it.'),note('<b>Before public release:</b> Mac build, installation and AU/VST3 validation passed. Target-DAW testing and real-vocal listening remain required. Consult the Release and Test Report for the exact executed coverage.')]
build('IRChoir-User-Guide.pdf','User guide',manual)

release=[]
release+=title('Release & audit report','I.R.Choir 0.3.2 - functional checks, fixes and release evidence.')
release+=[note(('<b>Automated release checks passed.</b> The final installer is repackaged with these documents and rechecked before publication.' if VALIDATED else '<b>Release-candidate document.</b> Publication requires the workflow gates below. The completed artifact includes current logs.')+' The package and DMG remain unsigned and unnotarized.'),h('Build and test gates'),table(['Gate','Recorded scope / status'],[['Universal Mac AU/VST3',AUDIT_STATUS+' - arm64 and x86_64 binaries and architecture checks.'],['Native DSP / processor / editor',AUDIT_STATUS+' - sample rates, blocks, modes, MIDI, state, audio sanitization, import formats, all 55 places and actual editor controls.'],['ASan and UBSan',AUDIT_STATUS+' - native DSP and full processor/editor tests; LeakSanitizer disabled. No ThreadSanitizer or real-time certification is claimed.'],['VST3 pluginval',AUDIT_STATUS+' - pinned 1.0.4, strictness 10, seed 12345, installed VST3.'],['Audio Unit auval',AUDIT_STATUS+' - aumf IrCh IrAu; installed Audio Unit.'],['Package installation',AUDIT_STATUS+' - mounted image, actual package installation, signature integrity and universal architectures.'],['Final document refresh','Current manuals are generated after the first successful gates; the final DMG is installed and validated again before it is offered.']],[132,384]),p(('Workflow '+RUN+'. ' if RUN else 'See the successful workflow linked in PACKAGE-INFO.json. ')+('Code commit: '+COMMIT+'. ' if COMMIT else '')+'Runtime checks run on Apple Silicon. Intel execution and your DAW remain separate checks. Raw evidence accompanies the installer.','IRSmall')]
release+=[PageBreak()]+title('Audit findings and corrections')
release+=[table(['Finding','Correction and regression coverage'],[['Missing/empty project file','Invalidates previous audio immediately and keeps the missing reference for relinking; empty references clear readiness. Real asynchronous restore tests cover both.'],['Stale background load','Generation tracking prevents an older worker from publishing after a later restore or clear request.'],['Empty-player playback','Play cannot start without ready audio. The UI disables Play while no file is ready or loading.'],['Factory-preset undo','Parameters reset to defaults and preset metadata now belong to the same undo transaction.'],['Preset identity after reopening','Current preset key is retained in project state; no unrelated favourite is assumed for unsaved settings.'],['Malformed audio/state','Non-finite state numbers are rejected with locale-independent parsing. Invalid or extreme input samples are sanitized before internal DSP.'],['Stale meters after reset','Reset clears detected pitch, mono RMS, correlation, peaks and clipping indication.'],['Audio callback lookups','Global parameters are cached so repeated string construction and parameter-map lookups are removed from audio processing.'],['Reverb display','Illustrated category-driven room and relative shape plot; hidden choir hit targets are inactive on this page.']],[132,384]),h('Additional functional coverage'),p('WAV, AIFF and FLAC import; sample-rate conversion; file/DAW switching; loop/end/stop; relink after missing files; all 55 place designs; reverb toggles; MIDI release/sustain/panic; custom preset save/load; favourites; A/B; formation, grouping, conductor and singer drag/mute; resizing and actual native snapshots.'),p('Tests use generated audio. They validate software behavior and memory/undefined-behavior checks; they do not judge human lyric intelligibility or natural choir realism.','IRSmall')]
release+=[PageBreak()]+title('Install, verify and remove')
release+=[h('Install the current build'),p('Quit your DAW. Open I.R.Choir-0.3.2-unsigned.dmg and run the .pkg inside it. The package places IRChoir.component in /Library/Audio/Plug-Ins/Components and IRChoir.vst3 in /Library/Audio/Plug-Ins/VST3. Restart and rescan your DAW.'),h('Confirm basic operation'),p('Load a short isolated vocal. Press Play, choose Unison and Intimate or Wide, then adjust Choir Mix. Check reverb, mono and output level at moderate monitoring volume. In some hosts the audio engine or transport must be running before plugin playback is processed.'),h('Rebuild and provenance'),p('The package source and checksum manifest identify the code commit and workflow. Repository: https://github.com/trendyspenders-hub/IRchoir. Build on Mac with CMake and Xcode command line tools using bash Scripts/build-mac.sh. JUCE 8.0.6 and source licenses are included with the default installer. Documentation fonts have their own included license.'),h('Signing status'),p('Plugin bundles have ad-hoc signatures for integrity. Developer ID signing and Apple notarization are not performed. Existing build options accept your own Application/Installer certificates and an existing notary profile. Do not disable Gatekeeper globally.'),h('Remove the plugin'),p('Quit the DAW and remove only the two installed bundles above, then rescan. Presets and recordings are stored separately. Actual uninstall and preset-preservation behavior in every target DAW is not established by the automated installation check.')]
release+=[PageBreak()]+title('Known limits and next checks')
release+=[table(['Area','Practical limit'],[['Your DAW / Intel runtime','Universal binaries are built and checked. Real Intel execution, DAW scanning/routing and long sessions still need target-machine testing.'],['Choir realism','The engine uses processed layers and tonal colors, without trained singer identities or formant preservation.'],['Words and consonants','The original recorded words carry through the audio. Strong pitch shifts and MIDI pitch-confidence gating can soften or remove unvoiced consonants.'],['Imported playback','Manual transport; no host synchronization or built-in audio export. Keep original files because projects reference paths.'],['Audio quality','Imported-file conversion uses linear interpolation; saturation has no oversampling. Proposed DSP libraries in the research review are not integrated.'],['Timing and tails','Intentional layer delays are not DAW-compensated. The host tail estimate is 45 seconds; Freeze can sustain beyond that. Set host export tails deliberately.'],['55 place designs','Independent parameter profiles across six algorithms; not recorded venue acoustics or a commercial IR library.'],['Output','Clip indication is a sample-peak warning, not a true-peak limiter or LUFS meter.'],['Validation limits','No blind real-vocal listening study, full leak audit, ThreadSanitizer or hardware dropout guarantee. Conversion/deprecation warnings still require cleanup.']],[132,384]),h('Sound-quality priorities'),p('Next candidates: formant-aware pitch processing, consonant preservation, defined latency alignment, host-synchronized file playback, better sample-rate conversion, richer early/late reverb and optional loudness/true-peak metering. These are research recommendations, not hidden active features.'),p('Original code is AGPL-3.0-or-later. JUCE and bundled fonts retain their own terms. No commercial choir recordings, third-party impulse responses or AI weights are bundled. Review licenses before distribution.','IRSmall')]
build('IRChoir-Release-and-Test-Report.pdf','Release and audit report',release)
print('Created:',*[p.name for p in OUT.glob('*.pdf')])
